// ==============================================
// camera-on.js: a small "Camera on" mark in the corner of the screen
// ==============================================
// A red dot and the words "Camera on" show while the camera is running.
// This is for the person in front of the camera. They can see it is watching.
// Every camera example in Class 10 uses this same file.
//
//   drawCameraOn(cam);   // call it LAST in draw(), so it sits on top
//
// It checks the camera stream itself, so it shows only while a video track is live.
// It sits in the top right corner. On a laptop it moves left of the QR code while
// the QR code is showing.
//
// These sketches do not record or save the camera image. It stays on this device.
//
// For the p5.js Web Editor, upload this file next to sketch.js and add
// <script src="camera-on.js"></script> to index.html.
// ==============================================

// true while the camera stream has a live video track
function cameraIsOn(cam) {
  const video = cam && cam.videoElement;
  const stream = video && video.srcObject;
  if (!stream || !stream.getVideoTracks) return false;
  return stream.getVideoTracks().some((track) => track.readyState === 'live');
}

function drawCameraOn(cam) {
  if (!cameraIsOn(cam)) return;

  // This draws straight on the canvas, so the sketch's colorMode, text size and
  // transforms never change how it looks.
  const ctx = drawingContext;
  ctx.save();
  const density = pixelDensity();
  ctx.setTransform(density, 0, 0, density, 0, 0);

  const label = 'Camera on';
  ctx.font = '600 13px system-ui, sans-serif';
  const labelWidth = ctx.measureText(label).width;
  const boxHeight = 26;
  const boxWidth = 10 + 10 + 6 + labelWidth + 10;

  // Top right corner. A laptop QR code sits there too, so step left of it.
  let right = width - 14;
  const qr = document.getElementById('p5phoneDesktopQr');
  if (qr) right = Math.min(right, qr.getBoundingClientRect().left - 10);
  const left = right - boxWidth;
  const top = 14;

  // a dark pill so the words can be read over any picture
  const radius = boxHeight / 2;
  ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
  ctx.beginPath();
  ctx.moveTo(left + radius, top);
  ctx.arcTo(left + boxWidth, top, left + boxWidth, top + boxHeight, radius);
  ctx.arcTo(left + boxWidth, top + boxHeight, left, top + boxHeight, radius);
  ctx.arcTo(left, top + boxHeight, left, top, radius);
  ctx.arcTo(left, top, left + boxWidth, top, radius);
  ctx.closePath();
  ctx.fill();

  // the red dot, then the words
  ctx.fillStyle = '#ff3b30';
  ctx.beginPath();
  ctx.arc(left + 10 + 5, top + boxHeight / 2, 5, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, left + 10 + 10 + 6, top + boxHeight / 2 + 0.5);
  ctx.restore();
}

// ==============================================
// frame.js — downscaled camera frames for detectors that read pixels
// ==============================================
// Marker, QR and pixel detectors work on ImageData. Running them on a full
// camera frame is slow on phones, so this draws the current video frame into
// a small offscreen canvas first.
//
//   drawPhoneCamera(cam);                 // draw the feed (fit + mirror)
//   if (isNewFrame(cam)) { ... }          // once per camera frame (call once per draw)
//   const frame = grabFrame(cam, 480);    // longest side at most 480 px
//   frame.imageData                       // RGBA ImageData for the detector
//   frame.canvas                          // the offscreen canvas itself
//   frame.width, frame.height             // its size
//   const p = mapFramePoint(cam, frame, corner);  // frame px -> canvas px
//   const v = canvasToVideo(cam, mouseX, mouseY); // canvas px -> video px
//   drawOverCamera(cam, overlayImage);   // draw a frame-sized image on the video
//
// The frame is never mirrored. mapFramePoint() scales back up to video
// pixels and then uses PhoneCamera.mapPoint(), which applies the display
// fit and the mirror, so detections line up with image(cam, ...).
//
// For the p5.js Web Editor, upload this file next to sketch.js and change
// the <script src> in index.html to "frame.js".
// ==============================================

let cvFrameCanvas = null;
let cvFrameContext = null;

function grabFrame(cam, maxSide = 480) {
  const video = cam.videoElement;
  if (!cam.ready || !video || video.readyState < 2 || !video.videoWidth) {
    return null;
  }

  const scale = Math.min(1, maxSide / Math.max(video.videoWidth, video.videoHeight));
  const frameWidth = Math.round(video.videoWidth * scale);
  const frameHeight = Math.round(video.videoHeight * scale);

  if (!cvFrameCanvas) {
    cvFrameCanvas = document.createElement('canvas');
    cvFrameContext = cvFrameCanvas.getContext('2d', { willReadFrequently: true });
  }
  if (cvFrameCanvas.width !== frameWidth || cvFrameCanvas.height !== frameHeight) {
    cvFrameCanvas.width = frameWidth;
    cvFrameCanvas.height = frameHeight;
  }

  cvFrameContext.drawImage(video, 0, 0, frameWidth, frameHeight);

  return {
    canvas: cvFrameCanvas,
    context: cvFrameContext,
    imageData: cvFrameContext.getImageData(0, 0, frameWidth, frameHeight),
    width: frameWidth,
    height: frameHeight,
    scale: scale
  };
}

// draw() usually runs at 60 fps and cameras deliver 30, so half the draw()
// calls see the same video frame again. isNewFrame(cam) is true once per new
// camera frame: use it to skip repeated work, or (for frame differencing)
// to avoid comparing a frame with itself.
const cvFrameCounts = new WeakMap();
let cvLastSeen = { video: null, count: -1, time: -1 };

function isNewFrame(cam) {
  const video = cam.videoElement;
  if (!cam.ready || !video || video.readyState < 2) return false;

  if (video.requestVideoFrameCallback && !cvFrameCounts.has(video)) {
    cvFrameCounts.set(video, 0);
    const countFrame = () => {
      cvFrameCounts.set(video, cvFrameCounts.get(video) + 1);
      video.requestVideoFrameCallback(countFrame);
    };
    video.requestVideoFrameCallback(countFrame);
  }

  if (cvLastSeen.video !== video) {
    cvLastSeen = { video: video, count: -1, time: -1 };
  }
  // requestVideoFrameCallback counts real frames. Without it, fall back to
  // the video clock, which also advances once per frame for camera streams.
  const count = cvFrameCounts.has(video) ? cvFrameCounts.get(video) : -1;
  const isNew = count >= 0 ? count !== cvLastSeen.count : video.currentTime !== cvLastSeen.time;
  cvLastSeen.count = count;
  cvLastSeen.time = video.currentTime;
  return isNew;
}

function mapFramePoint(cam, frame, point) {
  return cam.mapPoint(point.x / frame.scale, point.y / frame.scale);
}

// Draw the camera feed with its fit mode and mirror. Same result as
// image(cam, 0, 0), copied from p5-phone's ml5 examples. With p5.js 2.2.3,
// image(cam, ...) logs a friendly-error warning on every frame.
function drawPhoneCamera(cam) {
  const video = cam.videoElement;
  if (!cam.ready || !video || video.readyState < 2) return;
  const dims = cam.getDimensions();
  push();
  if (cam.mirror) {
    translate(width, 0);
    scale(-1, 1);
  }
  drawingContext.drawImage(video, dims.x, dims.y, dims.width, dims.height);
  pop();
}

// The reverse of cam.mapPoint(): a canvas point (a tap) to video pixels.
// inside is false when the point falls outside the drawn video.
function canvasToVideo(cam, x, y) {
  const dims = cam.getDimensions();
  if (!dims.width) return { x: 0, y: 0, inside: false };
  let localX = x - dims.x;
  const localY = y - dims.y;
  if (cam.mirror) localX = dims.width - localX;
  return {
    x: localX / dims.scaleX,
    y: localY / dims.scaleY,
    inside: localX >= 0 && localX <= dims.width && localY >= 0 && localY <= dims.height
  };
}

// Draw any image that covers the whole video frame (a mask, a depth map, a
// pixel overlay) exactly where image(cam, ...) put the video, mirror included.
function drawOverCamera(cam, overlay) {
  const dims = cam.getDimensions();
  if (!dims.width) return;
  push();
  if (cam.mirror) {
    translate(width, 0);
    scale(-1, 1);
  }
  image(overlay, dims.x, dims.y, dims.width, dims.height);
  pop();
}

// ==============================================
// loading.js — loading spinner and error panel drawn on the p5 canvas
// ==============================================
// Adapted from p5-phone's examples/ml5/ml5-loading.js, generalized for any
// model download (ml5, MediaPipe, YOLO, Transformers.js).
//
//   setLoading('Loading model')   show the spinner with a message
//   setLoading('Downloading', 0.4) show it with a progress bar (0..1)
//   clearLoading()                hide it
//   setError('Not supported')     show a sticky message panel instead
//   drawStatus()                  call LAST in draw() so it sits on top
//
// For the p5.js Web Editor, upload this file next to sketch.js and change
// the <script src> in index.html to "loading.js".
// ==============================================

let cvLoadingMessage = null;
let cvLoadingProgress = null;
let cvErrorMessage = null;

function setLoading(message, progress) {
  cvLoadingMessage = message || 'Loading';
  cvLoadingProgress = (typeof progress === 'number') ? constrain(progress, 0, 1) : null;
}

function clearLoading() {
  cvLoadingMessage = null;
  cvLoadingProgress = null;
}

function isLoading() {
  return cvLoadingMessage !== null;
}

function setError(message) {
  cvErrorMessage = message;
  clearLoading();
  console.error(message);
}

function drawStatus() {
  if (cvErrorMessage) {
    drawErrorPanel(cvErrorMessage);
  } else if (cvLoadingMessage) {
    drawLoadingSpinner(cvLoadingMessage, cvLoadingProgress);
  }
}

function drawLoadingSpinner(label, progress) {
  const centerX = width / 2;
  const centerY = height / 2;
  const radius = 34;
  const activeDot = frameCount % 12;

  push();
  resetMatrix();
  noStroke();
  fill(0, 180);
  rect(0, 0, width, height);

  for (let index = 0; index < 12; index += 1) {
    const angle = TWO_PI * index / 12;
    const alpha = map((index + 12 - activeDot) % 12, 0, 11, 255, 55);
    fill(255, alpha);
    circle(centerX + cos(angle) * radius, centerY + sin(angle) * radius, 9);
  }

  fill(255);
  textAlign(CENTER, CENTER);
  textSize(16);
  text(label, centerX, centerY + 70);

  if (progress !== null && progress !== undefined) {
    const barWidth = min(240, width - 60);
    fill(255, 60);
    rect(centerX - barWidth / 2, centerY + 92, barWidth, 6, 3);
    fill(255);
    rect(centerX - barWidth / 2, centerY + 92, barWidth * progress, 6, 3);
  }
  pop();
}

function drawErrorPanel(message) {
  const panelWidth = min(width - 32, 460);

  push();
  resetMatrix();
  noStroke();
  fill(0, 200);
  rect(0, 0, width, height);

  textSize(16);
  textAlign(CENTER, CENTER);
  textWrap(WORD);
  fill(30, 34, 44);
  rect((width - panelWidth) / 2, height / 2 - 90, panelWidth, 180, 10);
  fill(255);
  text(message, (width - panelWidth) / 2 + 20, height / 2 - 80, panelWidth - 40, 160);
  pop();
}

// Example 5: Face to Board (the laptop side)
// The camera watches your face. Tilt your head, and a servo on the Arduino tilts with it.
// Open your mouth, and the LED matrix on the board flashes.
// Made for a laptop and its webcam, in Chrome. A phone in Chrome on Android works too.
//
// It is the Class 10 example 05 Face Mesh with Bluetooth added. The face part is the same:
// ml5 FaceMesh finds 468 points on the face, and two numbers come from them.
//   headTilt    the angle of the line between the cheeks, in degrees. 0 is a level head
//   mouthOpen   the gap between the lips divided by the width of the face. 0 is closed
// This sketch turns them into two values for the board:
//   tilt    the head tilt as a servo angle, 0 to 180. 90 is a level head
//   mouth   true while the mouth is open past MOUTH_OPEN
//
// Arduino code for the board: FaceToBoard.zip
//   https://digitalfuturesocadu.github.io/f26-atelier1-examples/class-13/bluetooth/5-face-to-board/FaceToBoard.zip
// This sketch on the p5 Web Editor: https://editor.p5js.org/npuckett/sketches/l83G5eNmq
//
// Nothing is recorded or saved. The camera image stays on this device.
// A small red dot and the words "Camera on" show in the corner while the camera runs.

// 1. YOUR BOARD NUMBER
// Three digits, the same as BOARD_NUMBER in the Arduino code.
// On a page you did not edit, add ?board= and your number to the address: ...?board=007
const BOARD_NUMBER = new URLSearchParams(location.search).get('board') || '900';

// 2. THE ADDRESSES (UUIDs). They match the Arduino code.
const SERVICE_UUID = '19b10000-e8f2-537e-4f6c-d104768a1' + BOARD_NUMBER;
const TILT_UUID = '19b10001-e8f2-537e-4f6c-d104768a1' + BOARD_NUMBER;
const MOUTH_UUID = '19b10004-e8f2-537e-4f6c-d104768a1' + BOARD_NUMBER;

// 3. THE FEEL
const TILT_RANGE = 30;     // degrees of head tilt, left or right, that turn the servo all the way
const MOUTH_OPEN = 0.25;   // mouthOpen above this counts as open. Try 0.15 to 0.4

// the face (from 05 Face Mesh)
let cam;
let faceMesh;
let faces = [];
let mouthOpen = 0;
let headTilt = 0;

// what goes to the board, and what it has now
let tilt = 90;
let mouth = false;
let sentTilt = -1;
let sentMouth = null;
let sending = false;
let connectButton;

function setup() {
  createCanvas(windowWidth, windowHeight);
  textFont('system-ui');

  // 4. SET UP BLUETOOTH: one service, two values, both written by this page
  bleSetup({
    serviceUUID: SERVICE_UUID,
    characteristics: [
      { name: 'tilt', uuid: TILT_UUID, type: 'uint8', write: true },
      { name: 'mouth', uuid: MOUTH_UUID, type: 'bool', write: true }
    ]
  });
  connectButton = createButton('Connect');
  connectButton.position(20, 20);
  connectButton.mousePressed(connectOrDisconnect);

  // 5. THE CAMERA AND THE FACE MODEL (from 05 Face Mesh)
  cam = createPhoneCamera('user', true, 'contain');
  enableCameraTap('Tap to turn on the camera. Nothing is recorded.');
  setLoading('Waiting for the camera');
  cam.onReady(() => {
    setLoading('Loading FaceMesh');
    const options = { maxFaces: 1, refineLandmarks: false, runtime: 'mediapipe', flipped: false };
    faceMesh = ml5.faceMesh(options, () => {
      faceMesh.detectStart(cam.videoElement, gotFaces);
      clearLoading();
    });
  });
  lockGestures();

  // on a laptop, a QR code of this page (with ?board=) so you can open it on your phone
  showDesktopQr({ label: 'Open on your phone', size: 120 });
}

function gotFaces(results) {
  faces = results || [];
}

function draw() {
  background(16, 19, 24);
  drawPhoneCamera(cam);

  // 6. MEASURE THE FACE (from 05 Face Mesh)
  if (faces.length > 0) {
    const points = cam.mapKeypoints(faces[0].keypoints);
    const upperLip = points[13];
    const lowerLip = points[14];
    const leftSide = points[234];
    const rightSide = points[454];

    const faceWidth = dist(leftSide.x, leftSide.y, rightSide.x, rightSide.y);
    const lipGap = dist(upperLip.x, upperLip.y, lowerLip.x, lowerLip.y);
    mouthOpen = lerp(mouthOpen, lipGap / faceWidth, 0.4);
    const [screenLeft, screenRight] = leftSide.x < rightSide.x ? [leftSide, rightSide] : [rightSide, leftSide];
    headTilt = degrees(atan2(screenRight.y - screenLeft.y, screenRight.x - screenLeft.x));

    // 7. TURN THEM INTO VALUES FOR THE BOARD
    // the servo turns the wrong way? Swap 0 and 180
    tilt = round(map(headTilt, -TILT_RANGE, TILT_RANGE, 0, 180, true));
    mouth = mouthOpen > MOUTH_OPEN;

    // the cheek line and the lips, as in 05 Face Mesh
    stroke(255, 165, 0);
    strokeWeight(2);
    line(leftSide.x, leftSide.y, rightSide.x, rightSide.y);
    stroke(mouth ? color(255, 60, 60) : color(60, 120, 255));
    strokeWeight(5);
    line(upperLip.x, upperLip.y, lowerLip.x, lowerLip.y);
  }

  // 8. SEND WHAT CHANGED
  if (bleConnected && !sending) {
    sendToBoard();
  }

  drawPanel();
  drawStatus();      // the loading spinner, from loading.js
  drawCameraOn(cam);
}

// one write at a time. The mouth goes first: a flash should not wait for the servo
async function sendToBoard() {
  sending = true;
  if (mouth !== sentMouth) {
    const value = mouth;
    if (await bleWrite('mouth', value)) sentMouth = value;
  } else if (tilt !== sentTilt) {
    const value = tilt;
    if (await bleWrite('tilt', value)) sentTilt = value;
  }
  sending = false;
}

// the board just connected: send both again
function bleReady() {
  sentTilt = -1;
  sentMouth = null;
}

function connectOrDisconnect() {
  if (bleConnected) {
    bleDisconnect();
  } else {
    bleConnect();   // opens the list of boards. Pick Board- and your number
  }
}

function drawPanel() {
  const panelHeight = 64;
  noStroke();
  fill(10, 13, 18, 210);
  rect(0, height - panelHeight, width, panelHeight);
  fill(247);
  textSize(16);
  textAlign(LEFT, CENTER);
  let message = 'Show your face.';
  if (!cam.ready) message = 'Waiting for the camera.';
  else if (faces.length > 0) message = 'tilt ' + tilt + '   mouth ' + (mouth ? 'open' : 'closed') + '   (' + nf(mouthOpen, 1, 2) + ')';
  text(message, 16, height - panelHeight + 20);
  fill(180);
  textSize(14);
  let words = 'Not connected. Looking for Board-' + BOARD_NUMBER;
  if (bleConnected) words = 'Connected to ' + bleDeviceName;
  if (!bleSupported) words = 'No Bluetooth here. Use Chrome on a laptop or on Android.';
  text(words, 16, height - panelHeight + 44);
  connectButton.html(bleConnected ? 'Disconnect' : 'Connect');
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
